import{_ as e,o as l,c as i,O as r}from"./chunks/framework.db831a78.js";const m=JSON.parse('{"title":"工具 & 运维","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/10-工具运维.md","filePath":"interview/后端/Java/10-工具运维.md","lastUpdated":null}'),o={name:"interview/后端/Java/10-工具运维.md"};function t(d,a,h,c,u,n){return l(),i("div",null,a[0]||(a[0]=[r('<h1 id="工具-运维" tabindex="-1">工具 &amp; 运维 <a class="header-anchor" href="#工具-运维" aria-label="Permalink to &quot;工具 &amp; 运维&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解 深度标准：每个考点讲清「是什么 → 为什么 → 追问应对 → 易错点」。</p></blockquote><hr><h2 id="git-常用命令、merge-与-rebase-区别-★★☆" tabindex="-1">Git 常用命令、merge 与 rebase 区别 ★★☆ <a class="header-anchor" href="#git-常用命令、merge-与-rebase-区别-★★☆" aria-label="Permalink to &quot;Git 常用命令、merge 与 rebase 区别 ★★☆&quot;">​</a></h2><h3 id="常用命令" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令" aria-label="Permalink to &quot;常用命令&quot;">​</a></h3><ul><li><code>git init / clone / add / commit / push / pull / fetch / status / log / diff / branch / checkout / switch / merge / rebase / reset / revert / stash / tag</code>。</li></ul><h3 id="merge-vs-rebase" tabindex="-1">merge vs rebase <a class="header-anchor" href="#merge-vs-rebase" aria-label="Permalink to &quot;merge vs rebase&quot;">​</a></h3><ul><li>merge：保留分支历史，生成一个新的 merge commit，历史是「合并」的分叉结构。</li><li>rebase：把当前分支的提交「变基」到目标分支上，历史线性、干净，但改写提交历史（不适合已推送共享的分支）。</li></ul><h3 id="追问应对" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「merge 和 rebase 怎么选？」→ 公共分支用 merge（保留历史、安全），个人 feature 分支用 rebase 保持整洁。</li><li>「reset 和 revert 区别？」→ reset 回退（移动 HEAD，可能丢提交）；revert 生成反向提交（保留历史，安全）。</li></ul><hr><h2 id="maven-依赖冲突-★★☆" tabindex="-1">Maven 依赖冲突 ★★☆ <a class="header-anchor" href="#maven-依赖冲突-★★☆" aria-label="Permalink to &quot;Maven 依赖冲突 ★★☆&quot;">​</a></h2><h3 id="为什么冲突" tabindex="-1">为什么冲突 <a class="header-anchor" href="#为什么冲突" aria-label="Permalink to &quot;为什么冲突&quot;">​</a></h3><ul><li>传递依赖：A 依赖 B(1.0)，C 依赖 B(2.0)，同时引入 A、C 导致 B 版本冲突。</li></ul><h3 id="解决" tabindex="-1">解决 <a class="header-anchor" href="#解决" aria-label="Permalink to &quot;解决&quot;">​</a></h3><ul><li>最短路径优先、最先声明优先（Maven 默认原则）。</li><li>用 <code>&lt;exclusion&gt;</code> 排除某个传递依赖。</li><li><code>dependencyManagement</code> 统一管理版本。</li><li><code>mvn dependency:tree</code> 查看依赖树定位冲突。</li></ul><h3 id="追问应对-1" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-1" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「怎么定位依赖冲突？」→ <code>mvn dependency:tree</code> 看依赖树，找出冲突版本。</li></ul><hr><h2 id="docker-基础概念-★★☆" tabindex="-1">Docker 基础概念 ★★☆ <a class="header-anchor" href="#docker-基础概念-★★☆" aria-label="Permalink to &quot;Docker 基础概念 ★★☆&quot;">​</a></h2><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><ul><li>镜像（Image）：只读模板，分层构建。</li><li>容器（Container）：镜像运行实例，隔离但共享宿主机内核。</li><li>Dockerfile：构建镜像的脚本。</li><li>仓库（Registry）：存镜像（Docker Hub / 私有 Harbor）。</li></ul><h3 id="常用命令-1" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令-1" aria-label="Permalink to &quot;常用命令&quot;">​</a></h3><ul><li><code>docker build / run / ps / images / exec / logs / stop / rm / rmi / pull / push</code>。</li><li><code>docker run -d -p 8080:80 -v 宿主:容器 -e 环境变量 镜像</code>。</li></ul><h3 id="与虚拟机区别" tabindex="-1">与虚拟机区别 <a class="header-anchor" href="#与虚拟机区别" aria-label="Permalink to &quot;与虚拟机区别&quot;">​</a></h3><ul><li>虚拟机虚拟完整 OS（重、慢、隔离彻底）；容器共享内核（轻、快、秒级启动、隔离较弱）。</li></ul><h3 id="追问应对-2" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-2" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「镜像分层的好处？」→ 复用公共层、构建快、传输省空间。</li><li>「容器和镜像关系？」→ 镜像 + 可写层 = 容器；容器可 commit 成镜像。</li></ul><hr><h2 id="linux-常用命令-进程、日志、端口、内存-cpu-★★★" tabindex="-1">Linux 常用命令：进程、日志、端口、内存 CPU ★★★ <a class="header-anchor" href="#linux-常用命令-进程、日志、端口、内存-cpu-★★★" aria-label="Permalink to &quot;Linux 常用命令：进程、日志、端口、内存 CPU ★★★&quot;">​</a></h2><h3 id="进程" tabindex="-1">进程 <a class="header-anchor" href="#进程" aria-label="Permalink to &quot;进程&quot;">​</a></h3><ul><li><code>ps -ef | grep xxx</code>、<code>top</code>（实时）、<code>kill -9 pid</code>、<code>nohup ... &amp;</code>。</li></ul><h3 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h3><ul><li><code>tail -f xxx.log</code>、<code>tail -n 100</code>、<code>grep &#39;关键字&#39; xxx.log</code>、<code>less</code>。</li></ul><h3 id="端口与网络" tabindex="-1">端口与网络 <a class="header-anchor" href="#端口与网络" aria-label="Permalink to &quot;端口与网络&quot;">​</a></h3><ul><li><code>netstat -tlnp</code>、<code>ss -tlnp</code>（看监听端口）、<code>lsof -i:8080</code>。</li></ul><h3 id="内存-cpu" tabindex="-1">内存 CPU <a class="header-anchor" href="#内存-cpu" aria-label="Permalink to &quot;内存 CPU&quot;">​</a></h3><ul><li><code>free -h</code>（内存）、<code>top</code>/<code>htop</code>（CPU/内存）、<code>df -h</code>（磁盘）、<code>du -sh *</code>（目录大小）。</li></ul><h3 id="文件操作" tabindex="-1">文件操作 <a class="header-anchor" href="#文件操作" aria-label="Permalink to &quot;文件操作&quot;">​</a></h3><ul><li><code>cat/less/head/tail</code>（查看）、<code>find</code>（查找文件）、<code>chmod/chown</code>（权限）、<code>tar -zxvf</code>（解压）。</li></ul><h3 id="追问应对-3" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-3" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「CPU 飙高怎么查？」→ top 找进程 → top -Hp 找线程 → jstack 定位代码（配合 Java 进程）。</li></ul><hr><h2 id="常见安全-xss、csrf、sql-注入-★★★" tabindex="-1">常见安全：XSS、CSRF、SQL 注入 ★★★ <a class="header-anchor" href="#常见安全-xss、csrf、sql-注入-★★★" aria-label="Permalink to &quot;常见安全：XSS、CSRF、SQL 注入 ★★★&quot;">​</a></h2><h3 id="sql-注入" tabindex="-1">SQL 注入 <a class="header-anchor" href="#sql-注入" aria-label="Permalink to &quot;SQL 注入&quot;">​</a></h3><ul><li>原理：拼接 SQL 让用户输入变成 SQL 逻辑（<code>&#39; OR &#39;1&#39;=&#39;1</code>）。</li><li>防御：预编译（PreparedStatement/#{}）、参数校验、最小权限、ORM。</li></ul><h3 id="xss-跨站脚本" tabindex="-1">XSS（跨站脚本） <a class="header-anchor" href="#xss-跨站脚本" aria-label="Permalink to &quot;XSS（跨站脚本）&quot;">​</a></h3><ul><li>原理：注入恶意脚本到页面，窃取 cookie 等。</li><li>类型：存储型、反射型、DOM 型。</li><li>防御：输出转义、CSP、HttpOnly cookie、输入过滤。</li></ul><h3 id="csrf-跨站请求伪造" tabindex="-1">CSRF（跨站请求伪造） <a class="header-anchor" href="#csrf-跨站请求伪造" aria-label="Permalink to &quot;CSRF（跨站请求伪造）&quot;">​</a></h3><ul><li>原理：诱导用户在已登录状态访问恶意链接，冒用身份发请求。</li><li>防御：CSRF Token、SameSite cookie、验证 Referer、验证码。</li></ul><h3 id="追问应对-4" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-4" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「XSS 和 CSRF 区别？」→ XSS 利用信任「用户」注入脚本；CSRF 利用信任「浏览器/登录态」冒用身份。</li><li>「密码怎么存？」→ 加盐哈希（BCrypt/Argon2），不能明文、不能只 MD5。</li></ul><hr><h2 id="越权漏洞-idor-★★★" tabindex="-1">越权漏洞（IDOR）★★★ <a class="header-anchor" href="#越权漏洞-idor-★★★" aria-label="Permalink to &quot;越权漏洞（IDOR）★★★&quot;">​</a></h2><ul><li>水平越权：访问同级别他人数据（A 用户访问 B 用户订单，改 URL 的 id）。</li><li>垂直越权：低权限访问高权限功能。</li><li>防御：服务端鉴权（不能只前端隐藏按钮）、资源归属校验（查询时带 user_id 校验）、角色权限控制。</li></ul><h3 id="追问应对-5" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-5" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「前端隐藏了按钮就安全吗？」→ 不安全，接口要服务端做权限校验。</li></ul><hr><h2 id="线上排查完整流程-★★★" tabindex="-1">线上排查完整流程 ★★★ <a class="header-anchor" href="#线上排查完整流程-★★★" aria-label="Permalink to &quot;线上排查完整流程 ★★★&quot;">​</a></h2><ol><li>确认现象：报错信息、影响范围、是否可复现。</li><li>看监控：CPU、内存、GC、慢查询、接口耗时、错误率。</li><li>看日志：应用日志、错误堆栈、慢 SQL 日志。</li><li>定位： <ul><li>CPU 高 → top + jstack。</li><li>内存高/OOM → jmap dump + MAT 分析。</li><li>响应慢 → 慢 SQL、下游依赖、GC 频繁。</li><li>报错 → 堆栈定位代码。</li></ul></li><li>修复 + 验证 + 复盘（加监控告警、补测试）。</li></ol><h3 id="追问应对-6" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-6" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「接口超时怎么排查？」→ 看是否慢 SQL、下游服务慢、GC、网络；用链路追踪（traceId）定位耗时环节。</li></ul><hr><h2 id="线程-dump-分析-★★☆" tabindex="-1">线程 dump 分析 ★★☆ <a class="header-anchor" href="#线程-dump-分析-★★☆" aria-label="Permalink to &quot;线程 dump 分析 ★★☆&quot;">​</a></h2><ul><li>用途：分析线程状态、定位死锁、CPU 高、锁竞争。</li><li><code>jstack pid &gt; dump.txt</code>；关注 BLOCKED（等锁）、WAITING、RUNNABLE 状态，找死锁输出。</li></ul><h3 id="追问应对-7" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-7" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「jstack 看到大量 BLOCKED 说明什么？」→ 锁竞争严重，找持有锁的线程和锁对象。</li></ul><hr><h2 id="jvm-调优参数-★★☆" tabindex="-1">JVM 调优参数 ★★☆ <a class="header-anchor" href="#jvm-调优参数-★★☆" aria-label="Permalink to &quot;JVM 调优参数 ★★☆&quot;">​</a></h2><ul><li>见 JVM 篇：-Xms/-Xmx/-Xmn、-XX:MetaspaceSize、-XX:+UseG1GC、-XX:MaxGCPauseMillis、OOM dump 等。</li></ul><hr><h2 id="日志框架与监控体系-★★☆" tabindex="-1">日志框架与监控体系 ★★☆ <a class="header-anchor" href="#日志框架与监控体系-★★☆" aria-label="Permalink to &quot;日志框架与监控体系 ★★☆&quot;">​</a></h2><h3 id="日志-1" tabindex="-1">日志 <a class="header-anchor" href="#日志-1" aria-label="Permalink to &quot;日志&quot;">​</a></h3><ul><li>SLF4J + Logback/Log4j2；日志级别 TRACE/DEBUG/INFO/WARN/ERROR。</li><li>结构化日志（JSON）、traceId 贯穿、避免打印敏感信息。</li></ul><h3 id="监控" tabindex="-1">监控 <a class="header-anchor" href="#监控" aria-label="Permalink to &quot;监控&quot;">​</a></h3><ul><li>指标：Prometheus + Grafana；链路：SkyWalking/Zipkin；日志：ELK。</li><li>告警：CPU/内存/错误率/慢接口阈值告警。</li></ul><h3 id="追问应对-8" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-8" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么用 SLF4J？」→ 门面模式，统一日志接口，底层实现可替换。</li></ul>',78)]))}const b=e(o,[["render",t]]);export{m as __pageData,b as default};
